@app.get('/api/folders/{folder_id}/download-zip')
def download_folder_zip(
    folder_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    folder = db.query(StorageFolder).filter(StorageFolder.id == folder_id, StorageFolder.owner_id == current_user.id).first()
    if not folder or not os.path.isdir(folder.system_path):
        raise HTTPException(status_code=404, detail="Folder not found")

    zip_target = f"/tmp/archives/folder_{folder_id}.zip"
    shutil.make_archive(zip_target.replace(".zip", ""), 'zip', folder.system_path)
    return FileResponse(path=zip_target, filename=f"{folder.name}.zip", media_type="application/zip")
